using System.Text.Json;
namespace LocalChat;
static class CodeAudit {
 public static async Task<string> Check(string checker,string name,string text,string executable,CancellationToken ct){
  if(text.Length==0||text.Length>20000)throw new Exception("Для проверки нужен текст до 20 000 символов.");
  if(checker=="json"){try{using var doc=JsonDocument.Parse(text);return "JSON: синтаксис корректен. Содержимое и безопасность не проверялись.";}catch(JsonException e){return $"JSON: строка {e.LineNumber+1}, позиция {e.BytePositionInLine+1}: {e.Message}";}}
  if(checker is not ("ruff" or "bandit")||!name.EndsWith(".py",StringComparison.OrdinalIgnoreCase))throw new Exception("Доступны Ruff/Bandit для .py и проверка JSON. Исходный код не запускается.");
  var dir=Path.Combine(Path.GetTempPath(),"NORA-audit-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var path=Path.Combine(dir,"input.py");
  try{await File.WriteAllTextAsync(path,text,ct);var args=checker=="ruff"?new[]{"check","--isolated","--no-cache","--select","ALL","--ignore","D203,D213","--output-format=json",path}:new[]{"-q","-f","json",path};var result=await SafeProcess.Run(executable,args,45,ct);if(result.Exit is not (0 or 1))throw new Exception("Проверяющий завершился с ошибкой: "+result.Error[..Math.Min(1000,result.Error.Length)]);using var json=JsonDocument.Parse(result.Output);var items=checker=="ruff"?json.RootElement:json.RootElement.GetProperty("results");var rows=new List<string>();if(checker=="bandit"&&json.RootElement.TryGetProperty("errors",out var errors)&&errors.GetArrayLength()>0){foreach(var error in errors.EnumerateArray().Take(3))rows.Add("Файл не проверен: "+error.ToString());}int total=items.GetArrayLength();foreach(var item in items.EnumerateArray().Take(50)){if(checker=="ruff")rows.Add($"{name}:{item.GetProperty("location").GetProperty("row")}:{item.GetProperty("location").GetProperty("column")} [{item.GetProperty("code")}] {item.GetProperty("message")}");else rows.Add($"{name}:{item.GetProperty("line_number")} [{item.GetProperty("test_id")}, {item.GetProperty("issue_severity")}] {item.GetProperty("issue_text")}");}if(total>50)rows.Add($"Показаны первые 50 из {total} замечаний.");return checker+": "+(rows.Count==0?"замечаний по включённым правилам нет.":string.Join("\n",rows))+"\nЭто статический анализ, не запуск кода, не полная проверка и не гарантия безопасности.";}finally{try{Directory.Delete(dir,true);}catch{}}
 }
}
